const out = [];
for (let g = 0; g < 5; g++) {
    const pattern = (0x1F << (4 - g)) & 0x1F;
    out.push({ payload: { char: { index: g, rows: [0, pattern, pattern, pattern, pattern, pattern, pattern, 0] } } });
}
out.push({ payload: { clear: true } });
return [out];

const bar = Math.round(Number(msg.payload) / 100 * 16 * 5);
const cells = [];
for (let col = 0; col < 16; col++) {
    const fill = bar - col * 5;
    cells.push(fill >= 5 ? 4 : fill > 0 ? fill - 1 : 0x20);
}
return [
    { payload: { text: 'CPU load ' + Math.round(Number(msg.payload)) + '%   ', col: 0, row: 0 } },
    { payload: { cursor: { on: false, blink: false, col: 0, row: 1 } } },
    { payload: { chars: cells } }
];
